param([Parameter(Mandatory=$true)][string]$RepoRoot)
Set-StrictMode -Version Latest;$ErrorActionPreference="Stop"
function Die([string]$Code,[string]$Detail){throw($Code+":"+$Detail)}
function Require([bool]$Condition,[string]$Code,[string]$Detail){if(-not$Condition){Die $Code $Detail}}
function EnsureDir([string]$Path){if(-not(Test-Path -LiteralPath $Path -PathType Container)){New-Item -ItemType Directory -Force -Path $Path|Out-Null}}
function Write-Lf([string]$Path,[string]$Text){EnsureDir(Split-Path -Parent $Path);$t=($Text-replace"`r`n","`n")-replace"`r","`n";if(-not$t.EndsWith("`n")){$t+="`n"};[IO.File]::WriteAllText($Path,$t,[Text.UTF8Encoding]::new($false))}
function PathDrive([string]$Path){try{$r=[IO.Path]::GetPathRoot([IO.Path]::GetFullPath($Path));if($r.Length-ge2-and$r.Substring(1,1)-eq":"){return $r.Substring(0,1).ToUpperInvariant()}}catch{};return ""}
function VolumeFs([string]$Drive){if([string]::IsNullOrWhiteSpace($Drive)){return ""};try{foreach($v in @(Get-Volume -DriveLetter $Drive -ErrorAction Stop)){return [string]$v.FileSystem}}catch{};return ""}
function RunReceipt([string]$Script,[string]$Schema,[string[]]$ScriptArgs){$a=@("-NoProfile","-NonInteractive","-ExecutionPolicy","Bypass","-File",$Script);$a+=$ScriptArgs;$out=& powershell.exe @a;if($LASTEXITCODE-ne0){Die "CHILD_EXIT" ($Script+":"+[string]$LASTEXITCODE)};return (LDREC-ReadReceiptFromOutput $out $Schema (Join-Path $RepoRoot "schemas"))}

