$missingProbe=RunReceipt $probe "ld.device.destination_write_probe.receipt.v1" @("-RepoRoot",$RepoRoot,"-DestinationPath",$missing);Require (-not[bool]$missingProbe.write_probe_ok) "MISSING_DEST_WRITE" "";Require ([string]$missingProbe.error -eq "DESTINATION_MISSING") "MISSING_DEST_REASON" ([string]$missingProbe.error)
